const projects=[{name:'Órbita',type:'Identidade visual & experiência digital',year:'2026',color:'#2ec4b6',symbol:'O↗',word:'ÓRBITA STUDIO',desc:'Uma identidade que explora movimento, conexão e novas perspectivas. Formas geométricas e uma paleta vibrante dão vida a um universo digital próprio.',tags:['Branding','UI/UX','Desenvolvimento']},{name:'Alto Mar',type:'Estratégia de marca & e-commerce',year:'2026',color:'#7eb6e8',symbol:'≈',word:'ALTO MAR',desc:'Um conceito de marca inspirado na liberdade do oceano. Uma experiência de compra leve, com tipografia expressiva e navegação intuitiva.',tags:['Estratégia','E-commerce','Design']},{name:'Forma',type:'Direção de arte & website',year:'2025',color:'#ff9f3a',symbol:'F.',word:'FORMA OBJETOS',desc:'Um encontro entre matéria, função e design. Um catálogo digital que coloca as formas e suas histórias em primeiro plano.',tags:['Direção de arte','Web design']},{name:'Sereno',type:'Criação de marca',year:'2025',color:'#c6b5e5',symbol:'✳',word:'SERENO',desc:'Uma pausa no ritmo cotidiano. Uma marca conceitual com cores suaves, composição precisa e espaço para respirar.',tags:['Identidade visual','Branding']},{name:'Pixel Clube',type:'Plataforma criativa & desenvolvimento',year:'2025',color:'#e76b97',symbol:'P×',word:'PIXEL CLUBE',desc:'Um espaço digital para ideias compartilhadas. Interfaces modulares e detalhes lúdicos compõem uma plataforma voltada à comunidade criativa.',tags:['UI/UX','Plataforma','Código']},{name:'Nexo',type:'Design de produto & sistema visual',year:'2024',color:'#ffd23f',symbol:'N_',word:'NEXO DIGITAL',desc:'Conectar informação e ação através de uma linguagem visual direta. Um estudo de produto com foco em clareza e consistência.',tags:['Produto digital','Design system']}];
let selected=0,view='projects',sound=false,audio;const page=document.querySelector('#page');
const stripes='<div class="stripes" aria-hidden="true"><i></i><i></i><i></i><i></i></div>';
function beep(){if(!sound)return;try{audio??=new AudioContext();let o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=620;g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.07);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.07)}catch{}}
function art(p){return `<div class="art" style="--accent:${p.color}" role="img" aria-label="Identidade conceitual ${p.name}"><div class="art-grid"></div><span class="art-label">ESTUDO VISUAL / ${String(selected+1).padStart(2,'0')}</span><div class="art-logo"><span class="symbol">${p.symbol}</span><span class="word">${p.word}</span></div><span class="art-corner">DESIGN EM MOVIMENTO ↗</span></div>`}
function row(p,i){return `<button class="row ${selected===i?'selected':''}" data-project="${i}" aria-pressed="${selected===i}"><span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${p.name}</strong><small>${p.type}</small></span><span class="year">${p.year}</span></button>`}
function preview(){let p=projects[selected];document.querySelector('#preview').innerHTML=`${art(p)}<figcaption class="caption"><span>${p.name}</span><span>${p.year}</span></figcaption><div class="palette" style="--accent:${p.color}"><i></i><i></i></div><div class="project-note"><span>PROJETO ${String(selected+1).padStart(2,'0')} / 06</span><button class="open" id="open">EXPLORAR PROJETO ↗</button></div>`;document.querySelector('#open').onclick=()=>action('enter');document.querySelectorAll('[data-project]').forEach((el,i)=>{el.classList.toggle('selected',i===selected);el.setAttribute('aria-pressed',i===selected)})}
function render(){page.classList.remove('fade');void page.offsetWidth;page.classList.add('fade');document.querySelector('#location').textContent=view==='projects'?'PROJETOS':view==='detail'?'PROJETO / '+projects[selected].name.toUpperCase():'ÍNDICE';if(view==='projects'){page.innerHTML=`<h1>Projetos</h1>${stripes}<div class="projects"><div class="list" aria-label="Selecione um projeto">${projects.map(row).join('')}</div><figure class="preview" id="preview"></figure></div><p class="demo">SELEÇÃO DEMONSTRATIVA · IDENTIDADES E PROJETOS CONCEITUAIS</p><div class="globe" aria-hidden="true"></div>`;preview();document.querySelectorAll('[data-project]').forEach(el=>{el.onpointerenter=()=>{selected=+el.dataset.project;preview()};el.onfocus=()=>{selected=+el.dataset.project;preview()};el.onclick=()=>{selected=+el.dataset.project;view='detail';beep();render()}})}else if(view==='detail'){let p=projects[selected];page.innerHTML=`<div class="eyebrow">PROJETO ${String(selected+1).padStart(2,'0')} / 06 · ${p.year}</div><h1>${p.name}</h1>${stripes}<div class="detail"><div>${art(p)}<div class="caption"><span>EXPLORAÇÃO VISUAL</span><span>${p.year}</span></div></div><div><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><h2>${p.type}</h2><p>${p.desc}</p><h2>Do conceito à interface.</h2><p>Uma exploração de linguagem, composição e interação, pensada para criar uma presença digital memorável.</p><p class="demo">Este é um projeto demonstrativo. Substitua por seu trabalho, imagens e resultados.</p><button class="open" id="return">← VOLTAR AOS PROJETOS</button></div></div>`;document.querySelector('#return').onclick=()=>action('back')}else{page.innerHTML=`<div class="eyebrow">BEM-VINDO AO TERMINAL</div><h1>Ideias em<br>transmissão<span style="color:var(--orange)">_</span></h1>${stripes}<p>Design, identidade e código.<br>Explore um universo de projetos criativos.</p><div class="index-menu"><button class="row selected" id="projects"><span class="num">01</span><span><strong>Projetos</strong><small>Uma seleção de experimentos e possibilidades</small></span><span>↗</span></button></div><p class="demo">PORTFÓLIO DEMONSTRATIVO · PERSONALIZE COM A SUA HISTÓRIA</p>`;document.querySelector('#projects').onclick=()=>{view='projects';render()}}page.scrollTop=0}
function action(key){beep();if(key==='home')view='home';else if(key==='back')view=view==='detail'?'projects':'home';else if(key==='enter')view=view==='home'?'projects':'detail';else if(key==='prev'||key==='next'){selected=(selected+(key==='prev'?-1:1)+projects.length)%projects.length;if(view==='home')view='projects'}render()}
document.querySelectorAll('[data-key]').forEach(el=>el.onclick=()=>action(el.dataset.key));document.addEventListener('keydown',e=>{if(e.target.closest('.music-player, .music-queue, .music-video-panel, input, textarea, select, [contenteditable="true"]'))return;if(e.target.closest('button')&&(e.key==='Enter'||e.key===' '))return;let k={ArrowUp:'prev',ArrowLeft:'prev',ArrowDown:'next',ArrowRight:'next',Enter:'enter',Escape:'back',Home:'home'}[e.key];if(k){e.preventDefault();action(k)}});document.querySelector('#sound').onclick=e=>{sound=!sound;e.currentTarget.setAttribute('aria-pressed',sound);e.currentTarget.textContent='FX: '+(sound?'ON':'OFF');beep()};function tick(){document.querySelector('#clock').textContent=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}tick();setInterval(tick,1000);render();
